window.docContents[46].resolve({"/rules/PL1004/#PL1004-proof-shape":{"contents":"The replacement proof proves the same proposition. Kernel reduction (decide, rfl) is permitted, subject to the surface's foundation profile.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1004: Compiler-trusting proofs require separate classification","header":"Required proof shape","id":"/rules/PL1004/#PL1004-proof-shape"},"/rules/PL2003/#PL2003-proof-shape":{"contents":"The fix must not change the proposition or behavior being claimed; if it does, review the statement again.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2003: Claimed source must elaborate warning-free","header":"Required proof shape","id":"/rules/PL2003/#PL2003-proof-shape"},"/rules/PL3002/#PL3002-proof-shape":{"contents":"∀ xs, f.{us} xs = g.{us} xs over the reference's complete dependent domain, closed, with no additional hypotheses, admitted by the kernel. An actual domain hypothesis is legitimate; an extra premise such as False is not.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL3002: Checked execution requires admitted correspondence","header":"Required proof shape","id":"/rules/PL3002/#PL3002-proof-shape"},"/rules/PL4001/#PL4001-proof-shape":{"contents":"No proof obligation: the rule concerns document structure. Each classified fence is then checked by PL4002, PL4003 or PL4004.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4001: Documentation fences must have a valid classification","header":"Required proof shape","id":"/rules/PL4001/#PL4001-proof-shape"}});